#include <vector>

class Solution {
public:
    std::vector<std::vector<int>> specialGrid(int n) {
        int sz = 1 << n;
        std::vector<std::vector<int>> grid(sz, std::vector<int>(sz, 0));
        int count = 0;

        auto fill = [&](auto& self, int x1, int x2, int y1, int y2) -> void {
            if (x2 - x1 == 1) {
                grid[x1][y1] = count++;
                return;
            }
            int midR = (x1 + x2) / 2;
            int midC = (y1 + y2) / 2;
            self(self, x1, midR, midC, y2);
            self(self, midR, x2, midC, y2);
            self(self, midR, x2, y1, midC);
            self(self, x1, midR, y1, midC);
        };

        fill(fill, 0, sz, 0, sz);
        return grid;
    }
};

class Solution {
    private int count = 0;

    public int[][] specialGrid(int n) {
        int sz = 1 << n;
        int[][] grid = new int[sz][sz];
        count = 0;
        fill(grid, 0, sz, 0, sz);
        return grid;
    }

    private void fill(int[][] grid, int x1, int x2, int y1, int y2) {
        if (x2 - x1 == 1) {
            grid[x1][y1] = count++;
            return;
        }
        int midR = (x1 + x2) / 2;
        int midC = (y1 + y2) / 2;
        fill(grid, x1, midR, midC, y2);
        fill(grid, midR, x2, midC, y2);
        fill(grid, midR, x2, y1, midC);
        fill(grid, x1, midR, y1, midC);
    }
}

/**
 * @param {number} n
 * @return {number[][]}
 */
var specialGrid = function(n) {
    const sz = 1 << n;
    const grid = Array.from({ length: sz }, () => new Array(sz).fill(0));
    let count = 0;

    function fill(x1, x2, y1, y2) {
        if (x2 - x1 === 1) {
            grid[x1][y1] = count++;
            return;
        }
        const midR = Math.floor((x1 + x2) / 2);
        const midC = Math.floor((y1 + y2) / 2);
        fill(x1, midR, midC, y2);
        fill(midR, x2, midC, y2);
        fill(midR, x2, y1, midC);
        fill(x1, midR, y1, midC);
    }

    fill(0, sz, 0, sz);
    return grid;
};
